'use strict';
let portalMaster=false,portalRole='player',portalView='welcome',wizard=null,wizardStep=0;
const username=()=>C.user()?.email?.replace('@players.new-detroit.invalid','')||'';
async function goHome(){try{
 if(portalView==='wizard'&&wizard)rememberWizard();
 if(portalView==='editor'){await save();if(dirty||saving)throw Error('Сначала дождись сохранения. При ошибке нажми на статус синхронизации.');}
 clearTimeout(saveTimer);cloudRecord=null;history.replaceState(null,'',location.pathname);showWelcome();window.scrollTo(0,0);
 }catch(e){portalError(e);}}
function goBack(){if(portalView==='wizard'){rememberWizard();if(wizardStep>0){wizardStep--;rememberWizard();showWizard();window.scrollTo(0,0);}else showLibrary();}else if(portalView==='editor')showLibrary();else goHome();}
function purgeDeletedCard(id){
 for(const storage of [localStorage,sessionStorage]){try{E.clearCardCache(storage,id);}catch{}}
 if(cloudRecord?.id===id){clearTimeout(saveTimer);cloudRecord=null;card=E.blank(D);dirty=false;conflict=false;version++;history.replaceState(null,'',location.pathname);}
}
function confirmDeleteCharacter(record){
 if(!record)return;
 const id=record.id,revision=record.revision,name=record.data.nickname||record.data.name||'Без имени';
 modal('Удалить персонажа?',`<p>Ты уверен, что хочешь удалить карточку <strong>«${esc(name)}»</strong>?</p><p>Карточка, фото и выданные права доступа будут удалены из облака. Локальная копия в этом браузере тоже будет очищена. Восстановить удалённую карточку нельзя.</p><div class="delete-actions"><button id="cancel-character-delete">Отмена</button><button id="confirm-character-delete" class="danger">Да, удалить персонажа</button></div>`);
 $('#cancel-character-delete').onclick=closeModal;
 $('#cancel-character-delete').focus();
 $('#confirm-character-delete').onclick=async()=>{const button=$('#confirm-character-delete');button.disabled=true;try{
  await C.remove(id,revision);purgeDeletedCard(id);
  try{localStorage.setItem('nd-deleted-card',id);localStorage.removeItem('nd-deleted-card');}catch{}
  closeModal();$('#dialog').innerHTML='';await showLibrary();notify('Персонаж удалён. Локальная копия очищена.');
 }catch(e){error(e);button.disabled=false;}};
}
window.addEventListener('storage',e=>{if(e.key==='nd-deleted-card'&&e.newValue){const wasOpen=cloudRecord?.id===e.newValue;purgeDeletedCard(e.newValue);if(wasOpen||portalView==='library'){showLibrary();notify('Карточка удалена в другой вкладке.');}}});
function portalShell(title,subtitle,body){$('#app').innerHTML=`<div class="portal"><header class="portal-top"><button id="portal-home" class="portal-brand">N<span>D</span> <small>НЬЮ ДЕТРОИТ</small></button><span class="eyebrow">CHARACTER SYSTEM / 02</span>${C.user()?'<button id="portal-logout">Выйти</button>':''}</header><main class="portal-main">${portalView!=='welcome'?`<div class="page-navigation" aria-label="Навигация"><button id="page-back">← Назад</button><button id="page-home">⌂ На главную</button>${portalView==='wizard'?'<button id="page-library">Мои карточки</button>':''}</div>`:''}<div class="eyebrow">${portalRole==='master'?'ТЕРМИНАЛ МАСТЕРА':'ЛИЧНОЕ ДЕЛО'}</div><h1 tabindex="-1">${title}</h1><p class="portal-lead">${subtitle}</p>${body}<p id="portal-error" role="alert"></p></main><footer>NEW DETROIT <span>ТВОЯ ИСТОРИЯ. ТВОЙ СЛЕД.</span></footer></div>`;$('#portal-home').onclick=goHome;if($('#page-back'))$('#page-back').onclick=goBack;if($('#page-home'))$('#page-home').onclick=goHome;if($('#page-library'))$('#page-library').onclick=()=>{rememberWizard();showLibrary();};if($('#portal-logout'))$('#portal-logout').onclick=async()=>{try{await C.logout();portalMaster=false;cloudRecord=null;wizard=null;history.replaceState(null,'',location.pathname);showWelcome();}catch(e){portalError(e);}};}
function portalError(e){if($('#portal-error'))$('#portal-error').textContent=e.message;else notify(e.message);}
function showWelcome(){portalView='welcome';portalShell('Город ждёт тебя.','Выбери, с какой стороны истории ты войдёшь в Нью Детроит.',`<div class="role-grid"><button class="role-card" data-role="player"><span class="eyebrow">01 / ЛИЧНАЯ ИСТОРИЯ</span><strong>Игрок</strong><p>Создай персонажа. Открой свои карточки и те, к которым мастер выдал доступ.</p><span class="role-arrow">Войти в город ↗</span></button><button class="role-card" data-role="master"><span class="eyebrow">02 / УПРАВЛЕНИЕ ИГРОЙ</span><strong>Мастер</strong><p>Все персонажи, редактирование карточек и управление доступом игроков.</p><span class="role-arrow">Открыть терминал ↗</span></button></div><p class="hint">Режим мастера доступен только назначенному аккаунту.</p>`);document.querySelectorAll('[data-role]').forEach(b=>b.onclick=async()=>{portalRole=b.dataset.role;if(C.user())await enterPortal();else showLogin();});}
function showLogin(register=false){portalView='login';portalShell(register?'Новый житель.':'С возвращением.',portalRole==='master'?'Вход в терминал мастера. Введи свой логин и пароль.':'Войди по логину или создай аккаунт, чтобы начать свою историю.',`<form id="portal-login" class="panel auth-panel"><label class="field"><span>${register?'Логин':'Логин или email существующего аккаунта'}</span><input name="login" autocomplete="username" required ${register?'pattern="[A-Za-z0-9][A-Za-z0-9_-]{2,31}" minlength="3" maxlength="32"':''}></label>${register?'<p class="hint">3–32 символа: латинские буквы, цифры, дефис и подчёркивание. Регистр не важен.</p>':''}<label class="field"><span>Пароль</span><input name="password" type="password" minlength="6" maxlength="128" autocomplete="${register?'new-password':'current-password'}" required></label>${register?'<p class="hint">От 6 символов, без требований к цифрам или спецсимволам. Запомни логин и пароль: почта для регистрации не нужна.</p>':''}<button type="submit" class="yellow">${register?'Создать аккаунт':'Войти'}</button>${portalRole==='player'?`<button type="button" id="auth-switch">${register?'Уже есть аккаунт':'Зарегистрироваться'}</button>`:''}</form>`);if($('#auth-switch'))$('#auth-switch').onclick=()=>showLogin(!register);$('#portal-login').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{if(register)await C.signup(f.login.value,f.password.value);await C.login(f.login.value,f.password.value);await enterPortal();}catch(err){portalError(err);b.disabled=false;}};}
async function enterPortal(){try{await loadCatalog();portalMaster=await C.isMaster();if(portalRole==='master'&&!portalMaster){showWelcome();portalError(Error('У этого аккаунта нет прав мастера. Выбери режим игрока.'));return;}const id=cardId();if(id){await openCard(id);return;}await showLibrary();}catch(e){portalError(e);}}
async function showLibrary(){try{await save();if(dirty||saving)throw Error('Есть неотправленные изменения. Дождись сохранения или нажми на статус, чтобы разрешить конфликт.');clearTimeout(saveTimer);cloudRecord=null;portalView='library';history.replaceState(null,'',location.pathname);portalShell(portalRole==='master'?'Все личные дела.':'Мои персонажи.',portalRole==='master'?'Редактируй любую карточку и выдавай игрокам доступ.':`На связи: ${esc(username())}. Здесь только твои и доступные тебе персонажи.`,`<div class="library-toolbar"><button id="new-character" class="yellow">+ Создать персонажа</button><button id="refresh-library">Обновить</button></div><div id="character-grid" class="character-grid" aria-live="polite">Загружаем карточки…</div>`);$('#new-character').onclick=startWizard;if(portalMaster){const b=document.createElement('button');b.textContent='Редактор справочника';b.onclick=showCatalogAdmin;$('.library-toolbar').append(b);}try{if(sessionStorage.getItem(wizardKey()))$('#new-character').textContent='Продолжить создание';}catch{}$('#refresh-library').onclick=showLibrary;let rows=await C.list();if(portalRole==='player'&&portalMaster){const visible=await Promise.all(rows.map(async r=>r.owner_id===C.user().id||(await C.grants(r.id)).some(g=>g.email===C.user().email.toLowerCase())));rows=rows.filter((r,i)=>visible[i]);}if(portalView!=='library')return;$('#character-grid').innerHTML=rows.length?rows.map(r=>`<div class="character-entry"><button class="character-card" data-character="${esc(r.id)}"><span class="eyebrow">${r.owner_id===C.user().id?'МОЙ ПЕРСОНАЖ':portalRole==='master'?'КАРТОЧКА ИГРОКА':'ОБЩИЙ ДОСТУП'}</span><h2>${esc(r.data.nickname||r.data.name||'Без имени')}</h2><p>${esc((r.data.bio||'История ещё не написана.').slice(0,150))}</p><span class="micro">${new Date(r.updated_at).toLocaleString('ru-RU')}</span><span class="role-arrow">Открыть досье ↗</span></button>${portalMaster||r.owner_id===C.user().id?`<button class="card-delete" data-delete-character="${esc(r.id)}">Удалить персонажа</button>`:''}</div>`).join(''):'<section class="empty-library"><span class="eyebrow">ДОСЬЕ / 000</span><h2>Твоя история начинается здесь.</h2><p>Карточек пока нет. Нажми «Создать персонажа» — пройдём четыре шага вместе.</p></section>';document.querySelectorAll('[data-delete-character]').forEach(b=>b.onclick=()=>confirmDeleteCharacter(rows.find(r=>r.id===b.dataset.deleteCharacter)));document.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>openCard(b.dataset.character).catch(portalError));}catch(e){portalError(e);}}
const wizardKey=()=>`nd-creation-${C.user().id}`;
function rememberWizard(){try{sessionStorage.setItem(wizardKey(),JSON.stringify({card:wizard,step:wizardStep,version:2,shop:shopState}));}catch{notify('Черновик не поместился в браузере. Не закрывай страницу до создания карточки.');}}
function startWizard(){let adjusted=false;wizard=E.blank(D);shopState={items:{},free:[],mode:"kits"};wizardStep=0;try{const saved=JSON.parse(sessionStorage.getItem(wizardKey()));if(saved){wizard=E.validate(saved.card,D);shopState=saved.shop||{items:{},free:[],mode:"kits"};adjusted=wizard.skills.some(x=>x>2);wizard.skills=wizard.skills.map(x=>Math.min(2,x));wizardStep=Math.max(0,Math.min(3,saved.version===2?saved.step||0:(saved.step||0)+((saved.step||0)>0?1:0)));}}catch{}showWizard();if(adjusted){rememberWizard();notify('При создании максимум 2 на навык. Лишние очки возвращены для распределения.');}}
function showWizard(){portalView='wizard';if(wizardStep===1){showEquipment();return;}const titles=['Кто ты?','Стартовое оснащение','На что ты способен?','Что ты умеешь?'];const subtitles=['Все поля необязательны. Имя и история могут появиться уже во время игры.','','Распредели четыре значения: 2, 1, 1 и 0. Каждая характеристика отвечает за свой подход.','Распредели 4 + Нейропластичность очков. Один ранг стоит одно очко, максимум — 2.'];portalShell(titles[wizardStep],subtitles[wizardStep],`<ol class="wizard-steps">${['Личность','Оснащение','Характеристики','Навыки'].map((s,i)=>`<li ${i===wizardStep?'aria-current="step"':''} class="${i<=wizardStep?'reached':''}"><span>0${i+1}</span>${s}</li>`).join('')}</ol><form id="wizard-form">${wizardStep===0?`<div class="identity-wizard panel"><div><label class="photo-upload"><span id="photo-preview">${wizard.photo?`<img src="${esc(wizard.photo)}" alt="Портрет персонажа">`:'<b>+</b><span>Фото персонажа</span>'}</span><input id="wizard-photo" type="file" accept="image/jpeg,image/png,image/webp"><span>Выбрать фото</span></label><p class="hint">JPG, PNG или WebP, до 10 МБ.</p><button type="button" id="remove-photo">Убрать фото</button></div><div><div class="two-cols">${wizardField('Имя персонажа','name')}${wizardField('Никнейм персонажа','nickname')}</div>${wizardField('Возраст персонажа','age')}<label class="field"><span>Краткая предыстория</span><textarea name="bio" maxlength="20000" rows="5">${esc(wizard.bio)}</textarea></label></div></div>`:`<div id="wizard-budget" role="status" aria-live="polite" class="budget"></div><div class="wizard-stats">${(wizardStep===2?D.attributes:D.skills).map((x,i)=>`<article class="panel wizard-stat"><div class="stat-title"><h2>${esc(x.name==='Тень'?'Скрытность':x.name)}</h2><label><span class="sr-only">${esc(x.name)}</span><select name="rank-${i}" data-rank="${i}" aria-label="${esc(x.name)}">${Array.from({length:3},(_,v)=>`<option value="${v}" ${wizard[wizardStep===2?'attributes':'skills'][i]===v?'selected':''}>${v}</option>`).join('')}</select></label></div><p>${esc(x.description)}</p></article>`).join('')}</div>`}<div class="wizard-actions"><button type="button" id="wizard-back">${wizardStep?'← Назад':'← К списку'}</button><button type="button" id="wizard-home">На главную</button><button type="submit" class="yellow" id="wizard-next">${wizardStep===3?'Создать персонажа':'Далее →'}</button></div></form>`);
 $('#wizard-back').onclick=goBack;$('#wizard-home').onclick=goHome;
 if(wizardStep===0){for(const k of ['name','nickname','age','bio'])$('#wizard-form').elements[k].oninput=e=>{wizard[k]=e.target.value;rememberWizard();};$('#wizard-photo').onchange=uploadPortrait;$('#remove-photo').onclick=()=>{wizard.photo='';rememberWizard();showWizard();};}
 else {document.querySelectorAll('[data-rank]').forEach(el=>el.onchange=()=>{wizard[wizardStep===2?'attributes':'skills'][+el.dataset.rank]=+el.value;wizard.hp=3+wizard.attributes[0];rememberWizard();wizardBudget();});wizardBudget();}
 $('#wizard-form').onsubmit=async e=>{e.preventDefault();try{if(wizardStep===2&&!E.derive(wizard,D.catalog).validAttributes)throw Error('Нужны ровно 2, 1, 1 и 0.');if(wizardStep<3){wizardStep++;rememberWizard();showWizard();window.scrollTo(0,0);return;}wizard=ND_SHOP.apply(wizard,shopState,D);E.validateCreation(wizard,D);$('#wizard-next').disabled=true;const row=await C.create(E.validate(wizard,D));sessionStorage.removeItem(wizardKey());wizard=null;await openCard(row.id);notify('Персонаж создан. Снаряжение и остаток бюджета сохранены.');}catch(err){portalError(err);if($('#wizard-next'))$('#wizard-next').disabled=false;}};
}
function wizardField(label,key){return `<label class="field"><span>${label}</span><input name="${key}" maxlength="${key==='age'?10:200}" value="${esc(wizard[key])}"></label>`;}
function wizardBudget(){
 const d=E.derive(wizard,D.catalog),el=$('#wizard-budget');
 el.classList.toggle('skill-budget',wizardStep===3);
 el.classList.toggle('warning',wizardStep===2?!d.validAttributes:d.skillPoints<0);
 el.classList.toggle('complete',wizardStep===3&&d.skillPoints===0);
 if(wizardStep===2){el.textContent=d.validAttributes?'Распределение готово: 2 / 1 / 1 / 0':'Нужно распределить: 2 / 1 / 1 / 0';return;}
 const total=4+wizard.attributes[2],spent=total-d.skillPoints;
 el.innerHTML=`<div class="budget-number"><strong>${Math.abs(d.skillPoints)}</strong><span>${d.skillPoints<0?'ПЕРЕРАСХОД':'СВОБОДНЫЕ ОЧКИ'}</span></div><div class="budget-detail"><b>${d.skillPoints<0?'Превышен бюджет':d.skillPoints===0?'Все очки распределены':'Распредели очки навыков'}</b><span>Потрачено ${spent} из ${total} · максимум 2 на навык</span><div class="budget-track" aria-hidden="true"><i style="width:${Math.min(100,spent/total*100)}%"></i></div></div>`;
}
async function uploadPortrait(e){const input=e.target,file=input.files[0];if(!file)return;const next=$('#wizard-next');next.disabled=true;try{const photo=await window.ND_PORTRAIT.crop(file);if(photo){wizard.photo=photo;rememberWizard();$('#photo-preview').innerHTML=`<img src="${photo}" alt="Портрет персонажа">`;}}catch(err){portalError(err);}finally{input.value='';next.disabled=false;}}
showWelcome();
if(cardId()){if(C.user())enterPortal();else showLogin();}
function editPortrait(){modal('Фото персонажа','<label class="field"><span>JPG, PNG или WebP, до 10 МБ</span><input id="edit-photo-file" type="file" accept="image/jpeg,image/png,image/webp"></label><p>После выбора файла можно настроить кадрирование.</p><button id="clear-photo">Убрать фото</button>');$('#clear-photo').onclick=()=>{card.photo='';changed();closeModal();render();};$('#edit-photo-file').onchange=async e=>{const input=e.target,file=input.files[0];if(!file)return;try{const photo=await window.ND_PORTRAIT.crop(file);if(photo){card.photo=photo;changed();closeModal();render();}}catch(e){error(e);}finally{input.value='';}};}
